Report.Query:
SELECT CAST([YEAR] AS NVARCHAR) +'-'+CAST([Month] AS NVARCHAR) AS Periodo ,ROUND(ISNULL(SUM(Comision),0),2) TotalComisionUSD ,ROUND(ISNULL(SUM(ComisionPagada),0),2) TotalComisionPagadaUSD ,ROUND(ISNULL(SUM(ComisionNoPagada),0),2) TotalComisionNoPagadaUSD ,ROUND(ISNULL(SUM(ComisionMX),0),2) TotalComisionMX ,ROUND(ISNULL(SUM(ComisionPagadaMX),0),2) TotalComisionPagadaMX ,ROUND(ISNULL(SUM(ComisionNoPagadaMX),0),2) TotalComisionNoPagadaMX FROM ( SELECT Amount as Comision ,CASE WHEN RC.Status = 2 then CD.Amount END ComisionPagada ,CASE WHEN RC.Status in (0,1) then CD.Amount END ComisionNoPagada ,(Amount * MoneyExchangeRateMxn) as ComisionMX ,CASE WHEN RC.Status = 2 then (CD.Amount * MoneyExchangeRateMxn ) END ComisionPagadaMX ,CASE WHEN RC.Status in (0,1) then (CD.Amount * MoneyExchangeRateMxn ) END ComisionNoPagadaMX ,Bs.[Year] ,Bs.[Month] FROM HotelBillingSystem..BillingStatements BS inner join OzUnivisit..Empresas E on E.IdEmpresa = BS.CompanyId and E.idPais = case when '@@@param3' = '1' then 'MX' else E.idPais end inner join HotelBillingSystem..ReservationCharges RC on BS.BillingStatementID = RC.BillingStatementID inner join HotelBillingSystem..CommissionDetails CD on RC.ReservationChargeID = CD.ReservationChargeID left join HotelBillingSystem..PaymentModel PM on PM.companyId =E.idEmpresa WHERE convert(char(10), BS.RegistrationDate, 111) >= '@@@param1' AND convert(char(10), BS.RegistrationDate, 111) <= '@@@param2' AND E.idPais = 'MX' and isnull(PM.Active,1) = case when '@@@param4' = '0' then 1 else isnull(PM.Active,1) end
) Rs
GROUP BY [YEAR],[Month] ORDER BY [YEAR],[Month]
